```python
# 1. basic class
class Cart:
    def __init__(self):
        self.items = []          # per-instance list

    def add(self, sku, qty=1):
        self.items.append((sku, qty))

    def count(self):
        return sum(q for _, q in self.items)

c = Cart()
c.add("pen"); c.add("book", 2)
print(c.count())
```

```python
# 2. __repr__ and a classmethod constructor
class Product:
    def __init__(self, sku, price):
        self.sku, self.price = sku, price
    def __repr__(self):
        return f"Product({self.sku!r}, {self.price})"
    @classmethod
    def from_row(cls, row):
        sku, price = row.split(",")
        return cls(sku, float(price))

print(Product.from_row("A1,99.5"))
```

```python
# 3. inheritance with super()
class Perishable(Product):
    def __init__(self, sku, price, days):
        super().__init__(sku, price)
        self.days = days

x = Perishable("milk", 55, 3)
print(isinstance(x, Product), x.days)
```

